INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29631, 0, 1033, 'DS0_Ms_A01_BetaSiteE1_LGT_01ClosedBetaSite', 'Engage and gather intel on the hostiles who have invaded the Beta Site. [Command Center]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29632, 0, 1033, 'DS1_Ms_A01_BetaSiteE1_LGT_01ClosedBetaSite', 'Fight through to the training range and deliver the evidence to Maj. Davis. [Command Center]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29633, 0, 1033, 'DS0_Ms_A01_BetaSiteE1_LGT_02BaksheuWho', 'Relieve Capt. Satterfield near the main administration building. [Command Center]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29634, 0, 1033, 'DS1_Ms_A01_BetaSiteE1_LGT_02BaksheuWho', 'Defeat the Baksheu leader Basemeton inside in the main administration building and cripple their assault. [Command Center]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29635, 0, 1033, 'DS2_Ms_A01_BetaSiteE1_LGT_02BaksheuWho', 'Find out what Basemeton was doing with the Command Center Terminal. [Command Center]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29636, 0, 1033, 'DS3_Ms_A01_BetaSiteE1_LGT_02BaksheuWho', 'Report the relief of the Command Center and the Bakesheu''s larger presence to Lt. Col. Carter. [Bunker]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29637, 0, 1033, 'DS0_Ms_A01_BetaSiteE1_LGT_03LyingDownOnTheJob', 'Locate the missing Nine Peaks Jaffa soldier Beror inside the main administration building. [Command Center]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29638, 0, 1033, 'DS1_Ms_A01_BetaSiteE1_LGT_03LyingDownOnTheJob', 'Locate the missing Nine Peaks Jaffa soldier Lamra''ac inside the command center barracks. [Command Center]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29639, 0, 1033, 'DS2_Ms_A01_BetaSiteE1_LGT_03LyingDownOnTheJob', 'Report the mysterious deaths of the Nine Peaks troops to Lt. Col. Carter. [Bunker]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (2964, 0, 1033, 'ITEM 3012 DISPLAY NAME', '');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29640, 0, 1033, 'DS0_Ms_A01_BetaSiteE1_LGT_04ShortGreyCavalry', 'Ascend to Mimir''s vessel by using the Asgard Teleportation device at its base. [Asgard Vessel]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29641, 0, 1033, 'DS1_Ms_A01_BetaSiteE1_LGT_04ShortGreyCavalry', 'Provide Mimir with the Baksheu intel and enlist his aid in the base''s defense. [Asgard Vessel]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29642, 0, 1033, 'DS2_Ms_A01_BetaSiteE1_LGT_04ShortGreyCavalry', 'Assist Mimir on the Scanning Station to track down signs of Baksheu technology. [Asgard Vessel]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29643, 0, 1033, 'DS4_Ms_B01_IhpCrater_DRK_03FreeingTheUnas', 'Report the effectiveness of the kill switch to Lt. Maggie McIntyre
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29644, 0, 1033, 'DS3_Ms_A01_BetaSiteE1_LGT_04ShortGreyCavalry', 'Disable the Baksheu Mines before they can do any damage. [Perimeter Two]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29645, 0, 1033, 'DS4_Ms_A01_BetaSiteE1_LGT_04ShortGreyCavalry', 'Sabotage the Bakesheu Stockpile of weapons to slow their counterattack. [Perimeter Two]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29646, 0, 1033, 'DS5_Ms_A01_BetaSiteE1_LGT_04ShortGreyCavalry', 'See if Mimir has uncovered anything further concerning the Baksheu offensive. [Asgard Vessel]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29647, 0, 1033, 'DS0_Ms_A01_BetaSiteE1_LGT_05ScientificMethod', 'Disable the device preventing ring transportation to the Science Facility. [Science Facility]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29648, 0, 1033, 'DS1_Ms_A01_BetaSiteE1_LGT_05ScientificMethod', 'Locate and relieve Capt. Tigges. [Science Facility]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29649, 0, 1033, 'DS2_Ms_A01_BetaSiteE1_LGT_05ScientificMethod', 'Override the Blast Door Switch to open up the facility. [Science Facility]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (2965, 0, 1033, 'ITEM 3013 DISPLAY NAME', '');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29650, 0, 1033, 'DS3_Ms_A01_BetaSiteE1_LGT_05ScientificMethod', 'Enter the Science Facility. [Science Facility]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29651, 0, 1033, 'DS4_Ms_A01_BetaSiteE1_LGT_05ScientificMethod', 'Get a situation report from Dr. Novak. [Science Facility Floor 01]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29652, 0, 1033, 'DS0_Ms_A01_BetaSiteE1_LGT_06StealingOurStuff', 'Secure the Artifact Display Case in the center of the room. [Science Facility Floor 01]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29653, 0, 1033, 'DS1_Ms_A01_BetaSiteE1_LGT_06StealingOurStuff', 'Secure the Recovered Tablets. [Science Facility Floor 01]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29655, 0, 1033, 'DS2_Ms_A01_BetaSiteE1_LGT_06StealingOurStuff', 'Secure the Crystal Key artifact. [Science Facility Floor 01]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29656, 0, 1033, 'DS3_Ms_A01_BetaSiteE1_LGT_06StealingOurStuff', 'Tell Dr. Novak the artifacts are safe and find out more about the Baksheu''s interest here. [Science Facility Floor 01]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29657, 0, 1033, 'MsIt_Fn_Harset_LOY_03LanToc_LanToc_fac_NAME', 'Lan''toc');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29658, 0, 1033, 'DS0_Ms_A01_BetaSiteE1_LGT_07EggheadRescue', 'Fight your way up to Dr. Nash and assist her. [Science Facility Floor 02]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29659, 0, 1033, 'DS1_Ms_A01_BetaSiteE1_LGT_07EggheadRescue', 'Ascend further and assist Dr. Dempster, if he is still alive. [Science Facility Floor 03]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (2966, 0, 1033, 'ITEM 3014 DISPLAY NAME', '');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29660, 0, 1033, 'DS0_Ms_A01_BetaSiteE1_LGT_08Stargazing', 'Protect Dr. Felger from Hosetmes, the Baksheu leader by the telescope. [Science Facility Floor 03]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29661, 0, 1033, 'DS1_Ms_A01_BetaSiteE1_LGT_08Stargazing', 'Make sure Dr. Felger is okay and ask about what the Baksheu were up to. [Science Facility Floor 03]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29662, 0, 1033, 'DS2_Ms_A01_BetaSiteE1_LGT_08Stargazing', 'Download the Baksheu''s astronomy target via the Telescope Interface. [Science Facility Floor 03]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29663, 0, 1033, 'DS3_Ms_A01_BetaSiteE1_LGT_08Stargazing', 'Report the clearing of the Science Facility and hand off the recovered intel to Lt. Col. Carter. [Bunker]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29664, 0, 1033, 'MsIt_Fn_Harset_LOY_03LanToc_LanToc_fac_DESC', 'A Jaffa ritual device for testing loyalty.');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29665, 0, 1033, 'DS0_Ms_A01_BetaSiteE1_LGT_09SoAboutThoseJaffa', 'Disable the Baksheu Mines at Perimeter One on your way through. [Perimeter One]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29666, 0, 1033, 'DS1_Ms_A01_BetaSiteE1_LGT_09SoAboutThoseJaffa', 'Rescue the detachment sent to find the Nine Peaks Leader Ras''nor. [Shoul''Ja Outpost]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29667, 0, 1033, 'DS0_Ms_A01_BetaSiteE1_LGT_10RumorsOfMyDemise', 'Fight through to the home of Ras''nor, Nine Peaks chieftain, and confirm his death. [Camp Shoul''Ja]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29668, 0, 1033, 'DS0_Ms_A01_BetaSiteE1_LGT_11Outbreak', 'Contact Mimir via transmitter for assistance in diagnosing Ras''nor''s illness.');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29669, 0, 1033, 'DS1_Ms_A01_BetaSiteE1_LGT_11Outbreak', 'Use the Medical Scanner provided by Mimir to assess Ras''nor''s condition. [Camp Shoul''Ja]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (2967, 0, 1033, 'ITEM 3015 DISPLAY NAME', 'Boron-Carbide Ablative Helmet');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29670, 0, 1033, 'DS2_Ms_A01_BetaSiteE1_LGT_11Outbreak', 'Use the Medical Scanner provided by Mimir to scan Ras''nor''s mother Alasha - who is apparently still healthy. [Camp Shoul''Ja]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29671, 0, 1033, 'DS3_Ms_A01_BetaSiteE1_LGT_11Outbreak', 'Contact Mimir via transmitter for the results of the analysis of the Nine Peak''s plague.');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29672, 0, 1033, 'DS4_Ms_A01_BetaSiteE1_LGT_11Outbreak', 'Though far from a cure, adminster Mimir''s temporary palliative to Ras''nor in the hopes of getting him lucid enough to talk. [Camp Shoul''Ja]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29673, 0, 1033, 'DS0_Ms_A01_BetaSiteE1_LGT_12MyThreeSons', 'Travel to the Shoul''Mur Teleporter in search of Ras''nor''s sons. [Ruins of Shoul''Mur]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29674, 0, 1033, 'DS1_Ms_A01_BetaSiteE1_LGT_12MyThreeSons', 'Question the injured Nine Peaks Jaffa Seshan as to the situation here. [Ruins of Shoul''Mur]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29675, 0, 1033, 'DS2_Ms_A01_BetaSiteE1_LGT_12MyThreeSons', 'Travel to Khenmer''Fa in search of the Baksheu archeologist Tirimose and recover the teleporter parts from her. [Ruins of Khenmer''Fa]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29676, 0, 1033, 'DS3_Ms_A01_BetaSiteE1_LGT_12MyThreeSons', 'Bring the teleporter parts back to Seshan so he can restore the rings to working order. [Ruins of Shoul''Mur]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29677, 0, 1033, 'DS0_Ms_A01_BetaSiteE1_LGT_13FollowTheBodies', 'Use the ring teleporter to transit to the second crater in search of Ras''nor''s sons. [Ruins of Shoul''Mur]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29678, 0, 1033, 'DS1_Ms_A01_BetaSiteE1_LGT_13FollowTheBodies', 'Follow the trail of deceased members of Jysic''s strike team in search of him. [Tretonin Facility]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29679, 0, 1033, 'DS2_Ms_A01_BetaSiteE1_LGT_13FollowTheBodies', 'Let Jysic know you''re hear to help. [Tretonin Facility]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (2968, 0, 1033, 'ITEM 3016 DISPLAY NAME', '');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29680, 0, 1033, 'DS0_Ms_A01_BetaSiteE1_LGT_14EngineeringReversed', 'Investigate the Tretonin Production Controls for a means to reverse the tretonin posioning afflicting the Nine Peaks. [Tretonin Facility]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29681, 0, 1033, 'DS1_Ms_A01_BetaSiteE1_LGT_14EngineeringReversed', 'Check out the main tretonin production vats in search of an alternative solution to the posioning. [Tretonin Facility]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29682, 0, 1033, 'DS2_Ms_A01_BetaSiteE1_LGT_14EngineeringReversed', 'Defeat the Dakor Follower Veric guarding the hostages here. [Tretonin Facility]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29683, 0, 1033, 'DS3_Ms_A01_BetaSiteE1_LGT_14EngineeringReversed', 'The Baksheu Ramsut seems to have surrendered. Interrogate him. [Tretonin Facility]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29684, 0, 1033, 'DS4_Ms_A01_BetaSiteE1_LGT_14EngineeringReversed', 'Inform Jysic that clean tretonin will not cure the plague and ask about his brothers. [Tretonin Facility]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29685, 0, 1033, 'DS0_Ms_A01_BetaSiteE1_LGT_15TreasureMapOfTheStars', 'Find out if Ras''nor''s son Senl''c has gotten any more answers from the Baksheu. [Ruins of Barak''Ka]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29686, 0, 1033, 'DS1_Ms_A01_BetaSiteE1_LGT_15TreasureMapOfTheStars', 'Investigate the "Starmap" Cartouche Senl''c says the Baksheu are obsessed with. [Ruins of Barak''Ka]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29687, 0, 1033, 'DS2_Ms_A01_BetaSiteE1_LGT_15TreasureMapOfTheStars', 'Perhaps one of the nearby Baksheu is responsible for damaging the Starmap Cartouche. Recover the missing piece from them. [Ruins of Barak''Ka]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29688, 0, 1033, 'DS3_Ms_A01_BetaSiteE1_LGT_15TreasureMapOfTheStars', 'Bring the Starmap piece to Senl''c in exchange for the story of his brother Trik''na. [Ruins of Barak''Ka]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29689, 0, 1033, 'DS0_Ms_A01_BetaSiteE1_LGT_16LastSonOfRasnor', 'Inform Lt. Col. Carter of Trik''na''s search for a cure to the Nine Peaks Plague on the world Men''Fa. [Bunker]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (2969, 0, 1033, 'ITEM 3017 DISPLAY NAME', '');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29690, 0, 1033, 'DS1_Ms_A01_BetaSiteE1_LGT_16LastSonOfRasnor', 'Bring the artifacts of Baksheu interest to Dr. Jackson and seek the SGU leadership''s assistance in getting to Men''Fa. [Omega Site: Command Center]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29691, 0, 1033, 'DS0_Ms_A01_BetaSiteE1_LGT_17TakeTwoOfThese', 'Deliver the cure for the Nine Peaks plague to Jysic for distribution to the afflicted. [Beta Site: Tretonin Facility]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29692, 0, 1033, 'DS0_Ms_A01_BetaSiteE1_LGT_18FallOfDakor', 'Force the traitorous Nine Peaks leader Dakor to answer for his crimes. [Meeting Circle]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29693, 0, 1033, 'DS1_Ms_A01_BetaSiteE1_LGT_18FallOfDakor', 'One of the followers of Dakor, Yoru, wishes to speak with you. [Meeting Circle]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29694, 0, 1033, 'DS0_Ms_A01_BetaSiteE1_LGT_19Nemhet', 'Confront the Baksheu commander responsible for the attack, Nemhet, and recover the Crystal Activator artifact. [Ruins of Hacet''Ma]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29695, 0, 1033, 'DS1_Ms_A01_BetaSiteE1_LGT_19Nemhet', 'Analyze the Baksheu Terminal for intel on their remaining forces. [Ruins of Hacet''Ma]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29696, 0, 1033, 'DS0_Ms_A01_BetaSiteE1_LGT_20HideAndSeek', 'Contact Mimir via transmitter and make him aware of the cloaked Baksheu Ha''tak.');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29697, 0, 1033, 'DS1_Ms_A01_BetaSiteE1_LGT_20HideAndSeek', 'Disable the backup Cloaking Field Generators in the Baksheu base to expose the Ha''tak. [Ruins of Hacet''Ma]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29698, 0, 1033, 'DS2_Ms_A01_BetaSiteE1_LGT_20HideAndSeek', 'Inform Mimir that the Ha''tak has been decloaked. [Ruins of Hacet''Ma]');
INSERT INTO texts (moniker_id, flags, language, moniker_name, text) VALUES (29699, 0, 1033, 'DS3_Ms_A01_BetaSiteE1_LGT_20HideAndSeek', 'Bring the news of the Baksheu''s defeat and the Crystal Activator to the SGU leadership. [Omega Site: Command Center]');
